const $=s=>document.querySelector(s);let state={user:null,series:[],settings:{},current:null,audio:new Audio()};
async function api(url,opt={}){let r=await fetch(url,{headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'请求失败');return d}
function nav(){return `<nav class="nav"><div class="brand"><div class="logo">✦</div><div>小A知识星球<small>A'S KNOWLEDGE PLANET</small></div></div><div class="links"><button onclick="home()">首页</button><button onclick="explore()">探索播客</button>${state.user?'<button onclick="wishWall()">许愿墙</button>':''}<button onclick="library()">我的图书馆</button>${state.user?'<button onclick="knowledgeReport()">知识报告</button><button onclick="mechaPage()">我的机甲</button><button onclick="petPage()">我的宠物</button>':''}<button onclick="about()">关于小A</button>${state.user?.role==='admin'?'<button onclick="admin()">管理后台</button>':''}<button class="primary" onclick="state.user?profile():auth()">${state.user?state.user.display_name:'登录 / 注册'}</button></div></nav>`}
async function boot(){[state.series,state.settings]=await Promise.all([api('/api/series'),api('/api/settings')]);let m=await api('/api/me');state.user=m.user;home()}
function home(){document.body.innerHTML=nav()+`<main><section class="hero"><div><div class="eyebrow">AI FOR KIDS · AI BY KIDS</div><h1>${state.settings.hero||'让每一个好奇的问题，都开启一场知识冒险！'}</h1><p>${state.settings.slogan}<br>小A用AI做给好奇孩子的知识播客。每一次播放，都是向宇宙发出的一个问题。</p><button class="primary" onclick="explore()">开始探索　→</button></div><div class="hero-art"><div class="orbit"></div><div class="rocket">🚀</div></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">FEATURED MISSIONS</div><h2>精选知识航线</h2></div><button class="ghost" onclick="explore()">查看全部 →</button></div><div class="grid">${state.series.slice(0,3).map(card).join('')}</div></section><section class="section"><div class="eyebrow">EXPLORE BY TOPIC</div><h2>选择你的探索方向</h2><div class="category">${[['⚔️','军事探索'],['🏛️','历史传奇'],['🤖','AI与未来'],['🔬','科学实验室'],['💻','编程与创造']].map(([i,c])=>`<button class="cat" onclick="explore('${c}')"><span>${i}</span>${c}<small class="muted">　发现新问题 →</small></button>`).join('')}</div></section><section class="section"><div class="card" style="background:linear-gradient(120deg,#eaf4ff,#f2edff);display:flex;gap:24px;align-items:center;flex-wrap:wrap"><div style="font-size:65px">🧑‍🚀</div><div><div class="eyebrow">A STORY IN THE MAKING</div><h2>一个孩子，也可以造一颗知识星球</h2><p class="muted">我是小A，来自上海的四年级学生。我喜欢军事、历史、科学、AI和编程，也喜欢把大问题讲给更多孩子听。</p><button class="primary" onclick="about()">认识小A</button></div></div></section></main><footer class="footer">${state.settings.copyright}</footer>`}
function card(s){return `<article class="card series-card"><div><div class="cover" style="${s.cover?'height:auto;min-height:112px;background:#eef4ff;padding:0;align-items:center;justify-content:center;':''}">${s.cover?`<img src="${s.cover}" alt="${s.title} 封面" style="width:100%;height:auto;max-height:360px;object-fit:contain;display:block">`:s.title}</div><div style="margin-top:14px"><span class="badge">${s.category}</span> <span class="muted">${s.age_range}</span><h3>${s.title}</h3><p class="muted">${s.subtitle}</p></div></div><button class="ghost" onclick="detail(${s.id})">查看航线详情 →</button></article>`}
function explore(cat=''){document.body.innerHTML=nav()+`<section class="section" style="padding-top:60px"><div class="eyebrow">MISSION CONTROL</div><h1>探索播客</h1><p class="muted">选择一个系列，先听一小段，再申请你的专属航线。</p><div class="chips" style="margin:22px 0"><button class="badge" onclick="explore('')">全部</button>${CATEGORIES.map(c=>`<button class="badge" onclick="explore('${c}')">${c}</button>`).join('')}</div><div class="grid">${state.series.filter(s=>!cat||s.category===cat).map(card).join('')}</div></section>`}
const CATEGORIES=['军事探索','历史传奇','AI与未来','科学实验室','编程与创造'];
async function detail(id){let d=await api('/api/series/'+id);state.current=d;document.body.innerHTML=nav()+`<section class="section"><button class="ghost" onclick="explore()">← 返回探索</button><div class="card" style="margin-top:15px"><div class="eyebrow">${d.series.category} · ${d.series.age_range}</div><h1>${d.series.title}</h1><p class="muted">${d.series.subtitle}</p><p>${d.series.description}</p><div class="chips">${d.series.tags.map(x=>`<span class="badge">#${x}</span>`).join('')}<span class="badge">${d.episodes.length} 集</span></div><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><h2>分集列表</h2>${d.episodes.map((e,i)=>`<div class="card" style="display:flex;align-items:center;gap:12px;margin:10px 0;padding:14px"><button class="primary" onclick="play(${d.series.id},${e.id},${d.entitled})">▶</button><div style="flex:1"><b>第${e.episode_no}集｜${e.title}</b><div class="muted">${e.description} · ${Math.floor(e.duration/60)}:${String(e.duration%60).padStart(2,'0')}</div></div><span class="badge">${i===0?'免费试听':'完整版'}</span></div>`).join('')}<div style="margin-top:20px">${action(d)}</div></div></section>`}
function action(d){if(!state.user)return `<button class="primary" onclick="auth()">登录后购买 / 联系小A</button>`;if(d.entitled)return `<span class="badge">✓ 已开通，可收听完整版</span>`;if(d.application==='pending')return `<span class="badge">已提交购买申请 · 等待小A确认</span>`;return `<button class="primary" onclick="purchase(${d.series.id})">购买 / 联系小A${d.series.price&&d.series.price!=='0'?` · ¥${d.series.price}`:''}</button>`}
function purchase(id){let s=state.series.find(x=>x.id===id)||state.current?.series;if(!s)return;let qr=state.settings.qr_visible==='1'&&state.settings.qr_image?`<img src="${state.settings.qr_image}" style="display:block;width:220px;max-width:100%;margin:15px auto;border-radius:14px">`:'';modal(`<h2>购买 / 联系小A</h2><p><b>《${s.title}》</b></p><p class="badge">价格：¥${s.price&&s.price!=='0'?s.price:'请联系小A确认'}</p><h3 style="margin-top:22px">添加小A微信号</h3><p class="muted">微信号：<b style="color:var(--ink)">${state.settings.wechat_id||'请在后台设置'}</b></p>${qr}<p class="muted" style="text-align:center">${state.settings.qr_note||'请添加小A微信号，转账相应金额，并发送你的注册账号。小A确认后会在后台为你开通整个系列。'}</p><button class="primary" onclick="apply(${id});close()">我已联系小A，提交开通申请</button>`)}
async function apply(id){try{await api('/api/apply/'+id,{method:'POST',body:'{}'});toast('申请已提交，等待小A确认开通。');detail(id)}catch(e){toast(e.message)}}
function play(sid,eid,ent){let full=ent||eid===1;state.audio.src=`/${full?'private-media':'media'}/${sid}/${eid}`;state.audio.play().catch(()=>{});let last=0;clearInterval(window.listenTimer);window.listenTimer=setInterval(()=>{if(state.user&&!state.audio.paused&&state.audio.currentTime>last){let delta=Math.min(10,Math.max(0,state.audio.currentTime-last));api('/api/listen',{method:'POST',body:JSON.stringify({episode_id:eid,position:Math.floor(state.audio.currentTime),delta:Math.floor(delta)})}).catch(()=>{});last=state.audio.currentTime}},10000);document.body.insertAdjacentHTML('beforeend',`<div class="player"><b>▶ ${full?'完整版':'试听'} · 第${eid}集</b><input type="range" min="0" max="100" value="0" oninput="state.audio.currentTime=state.audio.duration*this.value/100"><button class="ghost" style="color:#fff" onclick="state.audio.pause()">暂停</button></div>`);state.audio.onended=()=>{clearInterval(window.listenTimer);toast('本集播放完成，继续探索下一集吧！')}}
function auth(){modal(`<h2>进入知识星球</h2><p class="muted">登录后可以申请播客系列并收听已开通内容。</p><div class="form"><input id="uname" placeholder="账号 / 邮箱"><input id="pass" type="password" placeholder="密码"><input id="dname" placeholder="首次注册时填写昵称（可选）"><button class="primary" onclick="login(false)">登录</button><button class="ghost" onclick="login(true)">注册新账号</button></div>`)}
async function login(reg){try{let d=await api('/api/'+(reg?'register':'login'),{method:'POST',body:JSON.stringify({username:$('#uname').value,password:$('#pass').value,display_name:$('#dname').value})});state.user=d.user;close();toast('欢迎回来，'+state.user.display_name);home()}catch(e){toast(e.message)}}
async function library(){if(!state.user)return auth();let xs=await api('/api/library');document.body.innerHTML=nav()+`<section class="section"><div class="eyebrow">MY LAUNCHPAD</div><h1>我的图书馆</h1><p class="muted">每一条已开通航线，都是你提出过的一个好问题。</p>${xs.length?`<div class="grid">${xs.map(card).join('')}</div>`:`<div class="card"><h2>还没有已开通的航线</h2><p class="muted">去探索播客，申请你的第一颗知识星球吧。</p><button class="primary" onclick="explore()">去探索</button></div>`}</section>`}
function about(){document.body.innerHTML=nav()+`<section class="section"><div class="card" style="max-width:800px;margin:auto"><div class="eyebrow">ABOUT A</div><h1>Built by a Kid,<br>for Curious Kids.</h1><p style="font-size:19px;line-height:1.8">我是小A，来自上海的四年级学生。我用AI辅助创作儿童知识播客，喜欢军事、历史、科学、人工智能和编程。</p><p class="muted">这个网站从真实的创作和交付需求出发：让知识音频更好听、更容易管理，也让每一个好奇的问题都能找到下一站。</p><div class="chips"><span class="badge">AI for Kids</span><span class="badge">AI by Kids</span><span class="badge">原创知识</span></div></div></section>`}
async function admin(){try{let d=await api('/api/admin');document.body.innerHTML=nav()+`<main class="admin"><div class="eyebrow">MISSION CONTROL</div><h1>管理后台</h1><p class="muted">内容、用户和授权，在这里清晰掌控。</p><div class="grid"><div class="card"><b>播客系列</b><h2>${state.series.length}</h2><span class="muted">已发布系列</span></div><div class="card"><b>用户</b><h2>${d.users.length}</h2><span class="muted">注册用户</span></div><div class="card"><b>待处理申请</b><h2>${d.pending.filter(x=>x.status==='pending').length}</h2><span class="muted">等待确认</span></div></div><section class="section" style="padding:35px 0"><h2>开通申请</h2><table class="table"><tr><th>用户</th><th>系列</th><th>状态</th><th>操作</th></tr>${d.pending.map(x=>`<tr><td>${x.display_name}<br><small>${x.username}</small></td><td>${x.title}</td><td>${x.status}</td><td>${x.status==='pending'?`<button class="primary" onclick="decision('approve',${x.id})">确认开通</button> <button class="ghost" onclick="decision('reject',${x.id})">拒绝</button>`:'—'}</td></tr>`).join('')}</table><h2 style="margin-top:35px">授权管理</h2><table class="table"><tr><th>用户</th><th>系列</th><th>状态</th><th>操作</th></tr>${d.entitlements.map(x=>`<tr><td>${x.username}</td><td>${x.title}</td><td>${x.active?'有效':'已撤销'}</td><td>${x.active?`<button class="ghost" onclick="decision('revoke',${x.id})">撤销授权</button>`:'—'}</td></tr>`).join('')}</table><h2 style="margin-top:35px">网站设置</h2><div class="card form"><label>首页主文案<input id="sethero" value="${state.settings.hero||''}"></label><button class="primary" onclick="saveSetting('hero',$('#sethero').value)">保存设置</button></div></section></main>`}catch(e){toast(e.message)}}
async function decision(act,id){await api('/api/admin/'+act,{method:'POST',body:JSON.stringify({id})});toast('操作已保存');admin()};async function saveSetting(k,v){await api('/api/admin/setting',{method:'POST',body:JSON.stringify({key:k,value:v})});state.settings[k]=v;toast('设置已更新')}
function profile(){modal(`<h2>${state.user.display_name}</h2><p class="muted">${state.user.username}<br>${state.user.role==='admin'?'管理员':'探索者'}</p><button class="primary" onclick="api('/api/logout',{method:'POST'}).then(()=>{state.user=null;close();home()})">退出登录</button>`)}function contact(){let s=state.settings;if(s.qr_visible==='1'&&s.qr_image)return modal(`<h2>联系小A</h2><img src="${s.qr_image}" style="display:block;max-width:280px;width:100%;margin:18px auto;border-radius:16px"><p class="muted" style="text-align:center">${s.qr_note||''}</p>`);toast(s.qr_note||'小A暂未设置二维码，请稍后再来。')}function modal(x){document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="modal"><div class="modal-box"><button class="close" onclick="close()">×</button>${x}</div></div>`)}function close(){$('#modal')?.remove()}function toast(x){let e=document.createElement('div');e.className='toast';e.textContent=x;document.body.append(e);setTimeout(()=>e.remove(),2600)}boot();

// 管理后台：与 SQLite API 连接的内容、用户、授权和网站设置工作台
async function admin(){try{let d=await api('/api/admin');if(!Array.isArray(d.series)){let base=await api('/api/series');d.series=await Promise.all(base.map(async s=>{let x=await api('/api/series/'+s.id);return {...s,episodes:x.episodes||[]}}))}d.users=d.users||[];d.pending=d.pending||[];d.entitlements=d.entitlements||[];d.wishes=d.wishes||[];state.adminData=d;adminShell('podcasts')}catch(e){toast(e.message)}}
function adminShell(tab='podcasts'){let d=state.adminData||{};d.series=Array.isArray(d.series)?d.series:[];d.users=Array.isArray(d.users)?d.users:[];d.pending=Array.isArray(d.pending)?d.pending:[];d.entitlements=Array.isArray(d.entitlements)?d.entitlements:[];d.wishes=Array.isArray(d.wishes)?d.wishes:[];document.body.innerHTML=nav()+`<main class="admin"><div class="eyebrow">MISSION CONTROL</div><h1>管理后台</h1><p class="muted">小A知识星球 · 内容与权限控制中心</p><div class="chips admin-tabs"><button class="${tab==='podcasts'?'primary':'badge'}" onclick="adminShell('podcasts')">播客管理</button><button class="${tab==='users'?'primary':'badge'}" onclick="adminShell('users')">用户管理</button><button class="${tab==='applications'?'primary':'badge'}" onclick="adminShell('applications')">开通申请 <b>${d.pending.filter(x=>x.status==='pending').length}</b></button><button class="${tab==='entitlements'?'primary':'badge'}" onclick="adminShell('entitlements')">授权管理</button><button class="${tab==='wishes'?'primary':'badge'}" onclick="adminShell('wishes')">许愿墙管理</button><button class="${tab==='settings'?'primary':'badge'}" onclick="adminShell('settings')">网站设置</button></div><div id="admin-content" style="margin-top:24px">${tab==='podcasts'?adminPodcasts(d):tab==='users'?adminUsers(d):tab==='applications'?adminApplications(d):tab==='entitlements'?adminEntitlements(d):tab==='wishes'?adminWishes(d):adminSettings(d)}</div></main>`}
function adminPodcasts(d){return `<div class="section-head"><div><h2>播客系列</h2><p class="muted">新增、编辑、下架系列，管理每一集内容。</p></div><button class="primary" onclick="seriesForm()">＋ 新增播客</button></div><div class="grid">${d.series.map(s=>`<div class="card series-card"><div><div class="cover">${s.title}</div><h3>${s.title}</h3><p class="muted">${s.category} · ${s.episodes.length} 集 · ${s.published?'已发布':'已下架'}</p></div><div class="chips"><button class="ghost" onclick="seriesForm(${s.id})">编辑</button><button class="ghost" onclick="episodeManager(${s.id})">管理分集</button><button class="ghost" onclick="grantForSeries(${s.id})">用户授权</button><button class="ghost" onclick="deleteSeries(${s.id})">删除</button></div></div>`).join('')}</div>`}
function adminUsers(d){return `<h2>用户管理</h2><p class="muted">每个注册用户自动出现在这里，也可以由管理员管理宠物成长。</p><table class="table"><tr><th>用户</th><th>账号</th><th>宠物成长</th><th>已开通播客</th><th>管理</th></tr>${d.users.map(u=>{let es=d.entitlements.filter(x=>x.user_id===u.id&&x.active);return `<tr><td><b>${u.display_name}</b><br><small>${u.role}</small></td><td>${u.username}</td><td>${u.pet_type?`${u.pet_type} · ${u.pet_score||0} 分<br><button class="ghost" onclick="feedUser(${u.id})">成长 +1</button>`:'尚未选择'}</td><td>${es.map(x=>`<span class="badge">${x.title}</span>`).join(' ')||'暂无开通'}</td><td><button class="primary" onclick="grantForUser(${u.id})">开通播客</button></td></tr>`}).join('')}</table>`}
function adminApplications(d){return `<h2>开通申请</h2><table class="table"><tr><th>用户</th><th>系列</th><th>申请时间</th><th>状态</th><th>操作</th></tr>${d.pending.map(x=>`<tr><td>${x.display_name}<br><small>${x.username}</small></td><td>${x.title}</td><td>${x.created_at}</td><td>${x.status}</td><td>${x.status==='pending'?`<button class="primary" onclick="decision2('approve',${x.id})">确认开通</button> <button class="ghost" onclick="decision2('reject',${x.id})">拒绝</button>`:'—'}</td></tr>`).join('')}</table>`}
function adminEntitlements(d){return `<h2>授权管理</h2><button class="primary" onclick="grantForUser()">＋ 直接添加授权</button><table class="table" style="margin-top:15px"><tr><th>用户</th><th>系列</th><th>状态</th><th>操作</th></tr>${d.entitlements.map(x=>`<tr><td>${x.display_name||x.username}</td><td>${x.title}</td><td>${x.active?'有效':'已撤销'}</td><td>${x.active?`<button class="ghost" onclick="revoke(${x.user_id},${x.series_id})">撤销开通</button>`:'—'}</td></tr>`).join('')}</table>`}
function adminSettings(d){let s=state.settings;return `<h2>网站设置</h2><div class="card form"><label>首页主文案<input id="sethero" value="${s.hero||''}"></label><label>小A微信号<input id="wechatid" placeholder="例如：xiaoa123" value="${s.wechat_id||''}"></label><label>购买提示文字<input id="qrnote" value="${s.qr_note||''}"></label><label class="badge"><input id="qrvis" type="checkbox" ${s.qr_visible==='1'?'checked':''}> 显示二维码</label><div>${s.qr_image?`<img src="${s.qr_image}" style="width:180px;border-radius:14px">`:'<p class="muted">尚未上传二维码</p>'}</div><input id="qrfile" type="file" accept="image/png,image/jpeg,image/webp"><div class="chips"><button class="primary" onclick="saveAllSettings()">保存设置</button><button class="ghost" onclick="removeQr()">删除二维码</button></div></div>`}
function seriesForm(id){let s=state.adminData.series.find(x=>x.id===id)||{};modal(`<h2>${id?'编辑播客':'新增播客'}</h2><div class="form"><input id="sf-title" placeholder="播客名称" value="${s.title||''}"><input id="sf-sub" placeholder="副标题" value="${s.subtitle||''}"><textarea id="sf-desc" placeholder="介绍" style="min-height:100px;padding:12px;border:1px solid var(--line);border-radius:12px">${s.description||''}</textarea><select id="sf-cat">${CATEGORIES.map(c=>`<option ${c===s.category?'selected':''}>${c}</option>`).join('')}</select><input id="sf-age" placeholder="适合年龄" value="${s.age_range||'9-15岁'}"><input id="sf-tags" placeholder="标签，用逗号分隔" value="${(s.tags||[]).join(',')}"><input id="sf-price" type="number" min="0" step="0.01" placeholder="价格（元）" value="${s.price||'0'}"><label class="upload-label">选择本地封面图片<input id="sf-cover-file" type="file" accept="image/png,image/jpeg,image/webp"></label>${s.cover?`<img src="${s.cover}" style="max-width:180px;border-radius:12px">`:''}<label class="badge"><input id="sf-pub" type="checkbox" ${s.published!==false?'checked':''}> 发布</label><button class="primary" onclick="saveSeries(${id||0})">保存播客</button></div>`)}
async function saveSeries(id){let f=$('#sf-cover-file')?.files?.[0],cover=f?await new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)}):'';let old=state.adminData.series.find(x=>x.id===id)||{};let d={id:id||null,title:$('#sf-title').value,subtitle:$('#sf-sub').value,description:$('#sf-desc').value,category:$('#sf-cat').value,age_range:$('#sf-age').value,tags:$('#sf-tags').value,price:$('#sf-price').value,cover:cover||old.cover||'',published:$('#sf-pub').checked};await api('/api/admin/save-series',{method:'POST',body:JSON.stringify(d)});close();toast('播客已保存');admin()}
function deleteSeries(id){if(confirm('确定下架并删除这个播客系列吗？关联授权和单集将不再对前台显示。'))api('/api/admin/delete-series',{method:'POST',body:JSON.stringify({id})}).then(()=>{toast('播客已删除');admin()})}
function episodeManager(id){let s=state.adminData.series.find(x=>x.id===id);modal(`<h2>管理分集｜${s.title}</h2><button class="primary" onclick="episodeForm(${id})">＋ 新增单集</button><div style="margin-top:15px">${s.episodes.map(e=>`<div class="card" style="display:flex;gap:10px;align-items:center;margin:8px 0"><b style="width:35px">${e.episode_no}</b><span style="flex:1">${e.title}<br><small class="muted">${e.published?'已发布':'已下架'}</small></span><button class="ghost" onclick="episodeForm(${id},${e.id})">编辑</button><button class="ghost" onclick="deleteEpisode(${e.id},${id})">删除</button></div>`).join('')}</div>`)}
function episodeForm(sid,eid){let s=state.adminData.series.find(x=>x.id===sid),e=s.episodes.find(x=>x.id===eid)||{};modal(`<h2>${eid?'编辑单集':'新增单集'}</h2><div class="form"><input id="ef-no" type="number" placeholder="集数" value="${e.episode_no||s.episodes.length+1}"><input id="ef-title" placeholder="单集标题" value="${e.title||''}"><textarea id="ef-desc" placeholder="单集简介" style="min-height:90px;padding:12px;border:1px solid var(--line);border-radius:12px">${e.description||''}</textarea><input id="ef-duration" type="number" placeholder="时长（秒）" value="${e.duration||92}"><label>上传音频（MP3、M4A、WAV，不限制大小）<input id="ef-audio" type="file" accept="audio/mpeg,audio/mp4,audio/wav,audio/x-m4a"></label><label class="badge"><input id="ef-pub" type="checkbox" ${e.published!==false?'checked':''}> 发布</label><p class="muted">已有音频不选择新文件时会保留；新上传会替换本集音频。</p><button class="primary" onclick="saveEpisode(${sid},${eid||0})">保存单集</button></div>`)}
async function saveEpisode(sid,eid){let audio_data='';let f=$('#ef-audio').files[0];if(f){audio_data=await new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)})}let d={id:eid||null,series_id:sid,episode_no:$('#ef-no').value,title:$('#ef-title').value,description:$('#ef-desc').value,duration:$('#ef-duration').value,published:$('#ef-pub').checked};if(audio_data)d.audio_data=audio_data;await api('/api/admin/save-episode',{method:'POST',body:JSON.stringify(d)});close();toast('单集和音频已保存');admin()}
function deleteEpisode(id,sid){if(confirm('确定删除这集吗？'))api('/api/admin/delete-episode',{method:'POST',body:JSON.stringify({id})}).then(()=>{toast('单集已删除');close();admin()})}
function grantForUser(uid){let d=state.adminData;modal(`<h2>直接开通播客</h2><div class="form"><select id="grant-user">${d.users.map(u=>`<option value="${u.id}" ${u.id===uid?'selected':''}>${u.display_name}｜${u.username}</option>`).join('')}</select><select id="grant-series">${d.series.map(s=>`<option value="${s.id}">${s.title}</option>`).join('')}</select><button class="primary" onclick="grant()">确认开通</button></div>`)}
function grantForSeries(sid){let d=state.adminData;modal(`<h2>给用户开通｜${d.series.find(s=>s.id===sid).title}</h2><div class="form"><select id="grant-user">${d.users.map(u=>`<option value="${u.id}">${u.display_name}｜${u.username}</option>`).join('')}</select><input type="hidden" id="grant-series" value="${sid}"><button class="primary" onclick="grant()">确认开通</button></div>`)}
async function grant(){let uid=Number($('#grant-user').value),sid=Number($('#grant-series').value);try{await api('/api/admin/grant',{method:'POST',body:JSON.stringify({user_id:uid,series_id:sid})})}catch(e){let old=state.adminData.pending.find(x=>Number(x.user_id)===uid&&Number(x.series_id)===sid&&x.status==='pending');if(!old)throw e;await api('/api/admin/approve',{method:'POST',body:JSON.stringify({id:old.id})})}close();toast('已开通成功');admin()}
async function revoke(uid,sid){if(confirm('确定撤销这个用户的系列授权吗？')){await api('/api/admin/revoke-user-series',{method:'POST',body:JSON.stringify({user_id:uid,series_id:sid})});toast('授权已撤销');admin()}}
async function decision2(act,id){await api('/api/admin/'+act,{method:'POST',body:JSON.stringify({id})});toast('操作已保存');admin()}
async function saveAllSettings(){let f=$('#qrfile').files[0],img=state.settings.qr_image||'';if(f){if(f.size>2*1024*1024) return toast('二维码图片不能超过 2MB');img=await new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)})}for(let [key,value] of [['hero',$('#sethero').value],['wechat_id',$('#wechatid').value],['qr_note',$('#qrnote').value],['qr_visible',$('#qrvis').checked?'1':'0'],['qr_image',img]])await api('/api/admin/setting',{method:'POST',body:JSON.stringify({key,value})});state.settings=await api('/api/settings');toast('网站设置已保存');admin()}
async function removeQr(){await api('/api/admin/setting',{method:'POST',body:JSON.stringify({key:'qr_image',value:''})});state.settings.qr_image='';toast('二维码已删除');admin()}

const PETS=[['fox','森林小狐狸','森林','pets.png'],['owl','星夜猫头鹰','森林','pets.png'],['rabbit','探险兔兔','森林','pets.png'],['lion','草原小狮子','草原','pets.png'],['giraffe','长颈鹿宝宝','草原','pets.png'],['meerkat','草原猫鼬','草原','pets.png'],['cat','彩虹小猫','森林','pets-extra.png'],['dog','快乐小狗','森林','pets-extra.png'],['wolf','雪山小狼','森林','pets-extra.png'],['panda','竹林熊猫','森林','pets-extra.png'],['bear','森林小熊','森林','pets-extra.png'],['dolphin','海洋海豚','海洋','pets-extra.png']];
function petTileLegacy(type,large=false,score=0){return ''}
async function petPage(){let p;try{p=await api('/api/pet')}catch(e){p={pet_type:localStorage.getItem('planet_pet')||'',pet_score:Number(localStorage.getItem('planet_pet_score')||0),local:true}}if(!p.pet_type)return modal(`<h2>选择你的第一只宠物</h2><p class="muted">选择一个陪你探索知识星球的伙伴。</p><div class="grid">${PETS.map(x=>`<button class="card" onclick="selectPet('${x[0]}')">${petTile(x[0])}<b>${x[1]}</b><small class="muted">${x[2]}</small></button>`).join('')}</div>`);let level=Math.floor((p.pet_score||0)/10)+1;let type=PETS.find(x=>x[0]===p.pet_type);modal(`<h2>我的宠物｜${type[1]}</h2>${petTile(p.pet_type,true,p.pet_score)}<p style="text-align:center"><b>成长值 ${p.pet_score}</b> · 等级 ${level}</p><p class="muted" style="text-align:center">每开通一个播客，宠物自动增加 5 分。宠物成长由小A在后台管理。</p>`)}
async function selectPet(type){localStorage.setItem('planet_pet',type);try{await api('/api/pet/select',{method:'POST',body:JSON.stringify({pet_type:type})})}catch(e){}close();toast('宠物选择成功');petPage()}
async function feedPet(){try{let p=await api('/api/pet/feed',{method:'POST',body:'{}'});close();toast('宠物吃饱了，成长值 +1');petPage()}catch(e){let n=Number(localStorage.getItem('planet_pet_score')||0)+1;localStorage.setItem('planet_pet_score',n);close();toast('宠物吃饱了，成长值 +1');petPage()}}
async function feedUser(id){try{await api('/api/admin/pet-feed-user',{method:'POST',body:JSON.stringify({user_id:id})});toast('宠物成长值 +1');admin()}catch(e){toast('宠物成长失败：'+e.message)}}

let gameLoopId=null;
function gamePage(){home()}
let gameKeys={up:false,down:false,left:false,right:false},gameState={x:550,y:365,distance:0,done:false};
function gameStart(){gameState={x:550,y:365,distance:0,done:false};window.onkeydown=e=>{let k=e.key.toLowerCase();if(['arrowup','w'].includes(k))gameKeys.up=true;if(['arrowdown','s'].includes(k))gameKeys.down=true;if(['arrowleft','a'].includes(k))gameKeys.left=true;if(['arrowright','d'].includes(k))gameKeys.right=true};window.onkeyup=e=>{let k=e.key.toLowerCase();if(['arrowup','w'].includes(k))gameKeys.up=false;if(['arrowdown','s'].includes(k))gameKeys.down=false;if(['arrowleft','a'].includes(k))gameKeys.left=false;if(['arrowright','d'].includes(k))gameKeys.right=false};cancelAnimationFrame(gameLoopId);gameTick()}
function gameReset(){gamePage()}
function drawThirdPerson(ctx,x,y,car){ctx.save();ctx.translate(x,y);if(car){ctx.fillStyle='#263a4b';ctx.fillRect(-58,-37,116,48);ctx.fillStyle='#315873';ctx.beginPath();ctx.moveTo(-42,-37);ctx.lineTo(-27,-70);ctx.lineTo(30,-70);ctx.lineTo(48,-37);ctx.fill();ctx.fillStyle='#9bd8ef';ctx.fillRect(-20,-63,42,22);ctx.fillStyle='#111';ctx.beginPath();ctx.arc(-40,12,18,0,Math.PI*2);ctx.arc(40,12,18,0,Math.PI*2);ctx.fill();ctx.fillStyle='#777';ctx.beginPath();ctx.arc(-40,12,8,0,Math.PI*2);ctx.arc(40,12,8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ff5b44';ctx.fillRect(-48,-20,12,8);ctx.fillRect(36,-20,12,8);ctx.fillStyle='#fff';ctx.font='14px sans-serif';ctx.fillText('越野车',-27,42)}else{ctx.fillStyle='#172638';ctx.beginPath();ctx.arc(0,-61,20,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d89a72';ctx.beginPath();ctx.arc(0,-58,14,0,Math.PI*2);ctx.fill();ctx.fillStyle='#314967';ctx.fillRect(-27,-43,54,59);ctx.fillStyle='#d89a72';ctx.fillRect(-40,-35,13,47);ctx.fillRect(27,-35,13,47);ctx.fillStyle='#1f2e42';ctx.fillRect(-22,15,16,40);ctx.fillRect(6,15,16,40);ctx.fillStyle='#fff';ctx.font='14px sans-serif';ctx.fillText('探险家',-28,75)}ctx.restore()}
function gameTick(){let c=$('#gameCanvas');if(!c)return;let ctx=c.getContext('2d'),w=c.width,h=c.height;let moving=gameKeys.up||gameKeys.down||gameKeys.left||gameKeys.right;if(!gameState.done&&moving){let speed=gameState.distance>=5?2.6:1.6;gameState.x+=(gameKeys.right?speed:0)-(gameKeys.left?speed:0);gameState.y+=(gameKeys.down?speed*.55:0)-(gameKeys.up?speed*.55:0);gameState.x=Math.max(80,Math.min(w-80,gameState.x));gameState.y=Math.max(210,Math.min(430,gameState.y));gameState.distance=Math.min(10,gameState.distance+0.006)}let urban=gameState.distance>=8,car=gameState.distance>=5;let sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,urban?'#a9d7ff':'#8bd5ff');sky.addColorStop(1,urban?'#f8d8a8':'#b7e58c');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);ctx.fillStyle=urban?'#798da0':'#5a9b52';ctx.fillRect(0,310,w,h-310);if(!urban){for(let i=0;i<18;i++){let tx=((i*137-gameState.distance*50)%w+w)%w;ctx.fillStyle='#216542';ctx.beginPath();ctx.moveTo(tx,315);ctx.lineTo(tx+35,190+(i%3)*18);ctx.lineTo(tx+70,315);ctx.fill();ctx.fillStyle='#173f34';ctx.fillRect(tx+31,285,9,70)}}else{ctx.fillStyle='#8d99a6';for(let i=0;i<8;i++){let bx=i*155;ctx.fillRect(bx,220-(i%2)*30,100,130);ctx.fillStyle='#d7eaff';for(let j=0;j<3;j++)ctx.fillRect(bx+15+j*25,240-(i%2)*30,13,18);ctx.fillStyle='#8d99a6'}}ctx.strokeStyle='#e9d19c';ctx.lineWidth=45;ctx.beginPath();ctx.moveTo(0,430);ctx.quadraticCurveTo(w/2,360,w,420);ctx.stroke();ctx.fillStyle='#fff';ctx.font='bold 23px sans-serif';ctx.fillText(urban?'城市已抵达！':'A\'s Wild Trail',28,48);ctx.font='18px sans-serif';ctx.fillText(`${gameState.distance.toFixed(1)} / 10.0 km`,28,78);ctx.fillStyle='#10275c';ctx.fillRect(28,95,260,12);ctx.fillStyle='#ffd75e';ctx.fillRect(28,95,260*gameState.distance/10,12);drawThirdPerson(ctx,gameState.x,gameState.y,car);if(car&&!urban){ctx.fillStyle='#fff';ctx.font='18px sans-serif';ctx.fillText('你驾驶着越野车继续向城市前进',w-350,48)}if(urban){ctx.fillStyle='#10275c';ctx.font='bold 24px sans-serif';ctx.fillText('恭喜！你完成了 10 公里探险',w/2-170,125);gameState.done=true}$('#gameStatus').textContent=urban?'已抵达城市 · 探险完成':`${car?'越野车行驶中':'徒步探索中'} · ${gameState.distance.toFixed(1)} km`;gameLoopId=requestAnimationFrame(gameTick)}
const gameSprite=new Image();gameSprite.src='/assets/game-characters.png';
function drawThirdPerson(ctx,x,y,car){let bob=Math.sin(performance.now()/120)*2;if(gameSprite.complete&&gameSprite.naturalWidth){let sw=gameSprite.naturalWidth/2;let dw=car?260:150,dh=car?260:300;ctx.drawImage(gameSprite,car?sw:0,0,sw,gameSprite.naturalHeight,x-dw/2,y-dh+bob,dw,dh);if(!car){ctx.strokeStyle='#d89a72';ctx.lineWidth=7;let swing=Math.sin(performance.now()/130)*10;ctx.beginPath();ctx.moveTo(x-35,y-145);ctx.lineTo(x-47+swing,y-78);ctx.moveTo(x+35,y-145);ctx.lineTo(x+47-swing,y-78);ctx.stroke()}return}ctx.fillStyle='#18354d';ctx.beginPath();ctx.arc(x,y-60,18,0,Math.PI*2);ctx.fill();ctx.fillRect(x-25,y-42,50,70)}
