// 成长值达到 10 分后切换为更修长、更成熟的成长形态。
function petTile(type,large=false,score=0){let i=PETS.findIndex(x=>x[0]===type),a=PETS[i],j=a[3]==='pets-extra.png'?i-6:i,level=Math.floor(score/10)+1,grown=score>=10,asset=grown?(i<6?'pets-grown.png':'pets-extra-grown.png'):a[3],scale=1+Math.min(.12,(level-1)*.025),glow=level>=3?'0 0 30px #ffd75e,0 0 58px #7357dc88':level>=2?'0 0 22px #65c8ff':'0 5px 18px #183b8055';return `<div style="position:relative;transform:scale(${large?scale:1});width:${large?'260px':'100%'};max-width:100%;margin:10px auto;filter:${level>=2?'saturate(1.18) contrast(1.05)':'none'};box-shadow:${glow};border-radius:18px"><div style="width:100%;aspect-ratio:1.2;border-radius:18px;background-size:300% 200%;background-repeat:no-repeat;background-image:url('/assets/${asset}');background-position:${(j%3)*50}% ${Math.floor(j/3)*100}%"></div>${grown?'<span style="position:absolute;left:10px;bottom:8px;background:#10275c;color:white;padding:5px 9px;border-radius:10px;font-size:11px">成长形态：更修长、更帅气</span>':''}</div>`}

// Black-screen guard: render a self-contained Three.js fallback first. External GLB
// assets are optional enhancements and must never be able to stop the render loop.
function start3DGame(){
  const el=$('#game3d');
  if(!el)return;
  const fail=msg=>{el.innerHTML=`<div style="height:100%;display:grid;place-items:center;color:#fff;font:600 16px system-ui;background:#10275c;padding:24px;text-align:center">${msg}</div>`};
  const boot=()=>{try{build3DGame()}catch(err){console.error('3D initialization failed',err);fail('3D 初始化失败：'+(err&&err.message?err.message:'未知错误')+'。请检查浏览器是否支持 WebGL。')}};
  if(window.THREE){boot();return}
  const s=document.createElement('script');s.src='https://unpkg.com/three@0.128.0/build/three.min.js';s.onload=boot;s.onerror=()=>fail('Three.js 加载失败，当前网络无法取得 3D 引擎。');document.head.appendChild(s);
}

